function receiptQR(){if(location.pathname==='/tv')return;var area=document.getElementById('thermal-receipt-print-area');if(!area)return;var oldQr=area.querySelectorAll('[data-receipt-qr]');if(oldQr.length){for(var oq=1;oq<oldQr.length;oq++)oldQr[oq].remove();area.dataset.qrAdded='1';return}if(area.dataset.qrAdded)return;area.dataset.qrAdded='pending';api('state','GET').then(function(j){var s=j.settings||{},ds=s.displaySettings||{},items=Array.isArray(ds.qrCodes)?ds.qrCodes.filter(function(x){return x&&x.active!==false&&(x.imageUrl||x.url)}):[];if(!items.length){var links=Array.isArray(s.appointmentLinks)?s.appointmentLinks.filter(function(x){return x&&x.active!==false&&x.url}):[];if(!links.length&&s.appointmentUrl)links=[{url:s.appointmentUrl,name:s.appointmentSiteName||'دریافت نوبت آنلاین',description:s.appointmentDescription||'برای دریافت نوبت آنلاین، QR را اسکن کنید.'}];items=links;}if(!items.length)return;var x=items[0],src=x.imageUrl||('https://api.qrserver.com/v1/create-qr-code/?size=180x180&margin=2&data='+encodeURIComponent(x.url||''));if(!src)return;var box=document.createElement('div');box.dataset.receiptQr='1';box.style='margin-top:8px;text-align:center;border-top:1px dashed #cbd5e1;padding-top:7px';box.innerHTML='<div style="font-size:9px;font-weight:900;color:#334155;margin-bottom:4px">'+esc(x.name||x.title||'دریافت نوبت اینترنتی')+'</div><div style="display:flex;justify-content:center"><img alt="QR '+esc(x.name||x.title||'')+'" style="width:76px;height:76px;object-fit:contain;background:#fff" src="'+esc(src)+'"></div><div style="font-size:7px;color:#64748b;line-height:1.4;margin-top:3px">'+esc(x.description||'برای دریافت نوبت آنلاین، QR را اسکن کنید.')+'</div>';area.appendChild(box);area.dataset.qrAdded='1';}).catch(function(){});}
