function dailyAppointmentPlanner(){
 if(location.pathname!='/secretary')return;
 var doctorSel=document.getElementById('sec-select-doctor'),numberInput=document.getElementById('sec-input-queue-number');if(!doctorSel||!numberInput)return;
 var host=numberInput.parentElement; if(!host)return;
 if(!document.getElementById('daily-slot-manager-btn')){
   var row=document.createElement('div');row.id='daily-slot-manager-row';row.style='display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:7px';
   row.innerHTML='<button type="button" id="daily-slot-manager-btn">📋 مدیریت نوبت‌های روز پزشک</button><span id="daily-slot-capacity-badge">ظرفیت روزانه: —</span>';
   var btn=row.querySelector('#daily-slot-manager-btn');btn.style='padding:7px 10px;border-radius:8px;border:1px solid #4f46e5;background:#312e81;color:#fff;font-family:BTitr;font-size:11px;font-weight:900;cursor:pointer';
   var badge=row.querySelector('#daily-slot-capacity-badge');badge.style='font-size:10px;color:#93c5fd;padding:4px 8px;border-radius:999px;background:#0f172a;border:1px solid #334155';
   host.parentElement.appendChild(row);btn.onclick=openDailySlotModal;
 }
 if(!doctorSel.dataset.slotBadgeBound){
   doctorSel.dataset.slotBadgeBound='1';
   doctorSel.addEventListener('change',refreshDailySlotBadge);
   refreshDailySlotBadge();
 } else if(!document.getElementById('daily-slot-capacity-badge').dataset.loaded){
   refreshDailySlotBadge();
 }
}
function refreshDailySlotBadge(){
 var b=document.getElementById('daily-slot-capacity-badge'),sel=document.getElementById('sec-select-doctor');if(!b||!sel||!sel.value)return;
 b.dataset.loaded='0';api('queue-slots/get','POST',{doctorId:sel.value}).then(function(j){var p=j.plan||{},active=(p.slots||[]).filter(function(x){return x.isActive}).length;b.textContent='ظرفیت روزانه: '+(p.maxAppointments?faDigits(p.maxAppointments):'—')+' | فعال: '+faDigits(active);b.dataset.loaded='1'}).catch(function(){b.textContent='ظرفیت روزانه: —';b.dataset.loaded='1'});
}
function openDailySlotModal(){
 var sel=document.getElementById('sec-select-doctor');if(!sel||!sel.value)return alert('ابتدا پزشک را انتخاب کنید.');
 api('queue-slots/get','POST',{doctorId:sel.value}).then(function(j){var d=j.doctor||{},p=j.plan||{},max=p.maxAppointments||25;showDailySlotEditor(sel.value,d,max,p.slots||[]);}).catch(function(e){alert(e.message);});
}
