function bookingStatusTools(){
 if(location.pathname!='/secretary')return;var sel=document.getElementById('sec-select-doctor');if(!sel||!sel.value)return;var host=document.getElementById('daily-slot-manager-row')||sel.parentElement;if(!host)return;
 var box=document.getElementById('booking-status-tool');if(!box){box=document.createElement('span');box.id='booking-status-tool';box.style='display:inline-flex;align-items:center;gap:6px;flex-wrap:wrap';box.innerHTML='<span id="booking-status-label" style="font-size:10px;padding:5px 8px;border-radius:999px;border:1px solid #334155">وضعیت نوبت‌دهی: —</span><button id="booking-status-toggle" type="button" style="padding:7px 10px;border-radius:8px;border:1px solid #b45309;background:#451a03;color:#fde68a;font-family:BTitr;font-size:11px;cursor:pointer">تغییر وضعیت نوبت‌دهی</button>';host.appendChild(box);box.querySelector('#booking-status-toggle').onclick=function(){queueStateCached(true).then(function(j){var d=(j.doctors||[]).find(function(x){return String(x.id)===String(sel.value)});var closed=!!(d&&d.bookingClosed);return api('doctors/booking-status','POST',{doctorId:sel.value,closed:!closed})}).then(function(){window.__bastianQueueStateCache=null;window.dispatchEvent(new Event('bastian-state-refresh'));refreshBookingStatus()}).catch(function(e){alert(e.message)})};}
 refreshBookingStatus();
}
function refreshBookingStatus(){var sel=document.getElementById('sec-select-doctor'),lab=document.getElementById('booking-status-label'),btn=document.getElementById('booking-status-toggle');if(!sel||!sel.value||!lab)return;queueStateCached(true).then(function(j){var d=(j.doctors||[]).find(function(x){return String(x.id)===String(sel.value)}),closed=!!(d&&d.bookingClosed);lab.textContent=closed?'● نوبت‌دهی عمومی پایان یافته':'● نوبت‌دهی فعال است';lab.style.color=closed?'#fecaca':'#86efac';lab.style.borderColor=closed?'#7f1d1d':'#166534';lab.style.background=closed?'#3b1118':'#052e16';if(btn)btn.textContent=closed?'بازگشایی نوبت‌دهی':'اعلام پایان نوبت‌دهی';}).catch(function(){})}


var scheduled=false;function run(){if(scheduled)return;scheduled=true;setTimeout(function(){scheduled=false;try{addNav();numberBox();patientTools();/* unified 3.3.14 workspace */doctorNext();bulkDoctorTools();settingsAppointment();settingsDisplay();receiptQR();}catch(e){console.warn('Bastiyan enhancements:',e);}},300)}
if(document.body){var observer=new MutationObserver(run);observer.observe(document.body,{childList:true,subtree:true});}window.addEventListener('bastian-state-refresh',function(){window.__bastianQueueStateCache=null;run();});setTimeout(run,900);
